import React, { useState } from "react";
import "./App.css";
import { FaUser, FaShieldAlt } from "react-icons/fa";
import { MdOutlineSmokeFree, MdWork } from "react-icons/md";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function App() {
  const [age, setAge] = useState("");
  const [coverage, setCoverage] = useState("");
  const [occupation, setOccupation] = useState("");
  const [tobacco, setTobacco] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [plans, setPlans] = useState([]);
  const [formSubmitted, setFormSubmitted] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const formData = {
      age,
      coverage_amt: coverage,
      tobacco,
      occupation,
      prompt: "Tell me about all the available Insurance plans?",
    };

    try {
      const response = await axios.post("http://localhost:5000/res", formData, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      setPlans(response.data.plans); // Assuming plans is an array of sample plans returned from backend
      setFormSubmitted(true); // Update formSubmitted state to true after successful submission
      navigate("/query");
    } catch (error) {
      console.error("Error submitting the form", error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="app">
      {isLoading && (
        <div className="spinner-container">
          <div className="chat-spinner">
            <div className="chat-bubble"></div>
            <div className="chat-bubble"></div>
            <div className="chat-bubble"></div>
          </div>
        </div>
      )}
      <div className="chat-container">
        <div className="chat-box">
          <div className="message user-message">
            <span>User: What insurance plans are available?</span>
          </div>
          <div className="message bot-message">
            <span>
              Bot: Please fill in the following details to help me provide you
              with relevant insurance plans.
            </span>
          </div>
          {formSubmitted ? (
            <div className="plans-container">
              <h1>Sample Insurance Plans</h1>
              <ul>
                {plans.map((plan, index) => (
                  <li key={index}>
                    <strong>{plan.name}</strong>: {plan.description}
                  </li>
                ))}
              </ul>
              <p>These are sample plans. Actual plans may vary.</p>
            </div>
          ) : (
            <div className="form-container">
              <h1>Insurance Form</h1>
              <form onSubmit={handleSubmit}>
                <div className="form-group">
                  <label>
                    <FaUser className="icon" /> Age:
                    <input
                      type="number"
                      className="input-field"
                      min="18"
                      max="100"
                      placeholder="Enter your age"
                      value={age}
                      onChange={(e) => setAge(e.target.value)}
                      required
                    />
                  </label>
                </div>
                <div className="form-group">
                  <label>
                    <FaShieldAlt className="icon" /> Coverage:
                    <select
                      className="input-field"
                      value={coverage}
                      onChange={(e) => setCoverage(e.target.value)}
                      required
                    >
                      <option value="">Select Coverage</option>
                      <option value="5000000">0-50 lakh</option>
                      <option value="10000000">50 lakh - 1 crore</option>
                    </select>
                  </label>
                </div>
                <div className="form-group">
                  <label>
                    <MdOutlineSmokeFree className="icon" />
                    Tobacco:
                    <select
                      className="input-field"
                      value={tobacco}
                      onChange={(e) => setTobacco(e.target.value)}
                      required
                    >
                      <option value="">Tobacco:</option>
                      <option value="Yes">Yes</option>
                      <option value="No">No</option>
                    </select>
                  </label>
                </div>

                <div className="form-group">
                  <label>
                    <MdWork className="icon" /> Occupation:
                    <select
                      className="input-field"
                      value={occupation}
                      onChange={(e) => setOccupation(e.target.value)}
                      required
                    >
                      <option value="">Select Occupation</option>
                      <option value="Salaried">Salaried</option>
                      <option value="Self-Employed">Self-Employed</option>
                    </select>
                  </label>
                </div>
                <button type="submit" className="submit-button">
                  Submit
                </button>
              </form>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
